CREATE TABLE `lib_psgc_barangay` (
  `barangay_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Barangay ID: Primary Key of Barangay Library. {"label":"Barangay ID","visible":"false","searchable":"false","formtag":"hidden","list":"1","view":"0","add_edit":"1","alias":"id"}',
  `name` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Name: Name of Barangay. {"label":"Name","visible":"true","searchable":"true","formtag":"text","rules":"required|regex_match[/^[a-zA-Z0-9 ñÑ().''-_]+$/]","list":"1","view":"1","add_edit":"1","alias":"name"}',
  `code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Code: Code of Barangay. {"label":"Code","visible":"true","searchable":"true","formtag":"text","rules":"min_length[2]|regex_match[/^[a-zA-Z0-9 ()''-_]+$/]","list":"1","view":"1","add_edit":"1","alias":"code"}',
  `geocode` char(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT 'Geocode: Philippine Standard Geographic Code. {"label":"GeoCode","visible":"true","searchable":"true","formtag":"text","rules":"exact_length[9]|numeric","list":"1","view":"1","add_edit":"1"}',
  `psa_code` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PSA Code: Philippine Standard Authority Code. {"label":"PSA Code","visible":"true","searchable":"true","formtag":"text","rules":"required|exact_length[10]|numeric","list":"1","view":"1","add_edit":"1"}',
  `is_gida` enum('No','Yes') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'No' COMMENT 'Is GIDA: States if barangay is under GIDA. {"label":"Is GIDA","visible":"true","searchable":"false","formtag":"checkbox","rules":"required","list":"1","view":"1","add_edit":"1"}',
  `city_id` int unsigned NOT NULL COMMENT 'Foreign Key of City/Municipality. City/Municipality associated to the Barangay. {"label":"City/Municipality","visible":"false","searchable":"true","formtag":"select","rules":"required","list":"1","view":"0","add_edit":"1","joinfldval":"name","parent":"province_id","class":"rpmb child city"}',
  `dt_inserted` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Date/Time Inserted: Date and Time the record was inserted. {"label":"Date/Time Inserted","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0"}',
  `inserted_by` int unsigned DEFAULT NULL COMMENT 'Inserted By: User ID who inserted the record. {"label":"Inserted By","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0", "joinfldval":"username"}',
  `dt_updated` datetime DEFAULT NULL COMMENT 'Date/Time Updated: Date and Time the records was last updated through application. {"label":"Date/Time Last Updated","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0"}',
  `last_updated_by` int unsigned DEFAULT NULL COMMENT 'Last Updated By: User ID who last updated the record. {"label":"Last Updated By","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0", "joinfldval":"username"}',
  `archived` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Archived: State if record was archived or deleted. (0-False; 1-True). {"label":"Archived","visible":"false","searchable":"false","formtag":"text","list":"0","view":"0","add_edit":"0","archive":"1","defaultzero":"1","archive":"1","defaultzero":"1","alias":"archived"}',
  `dt_archived` datetime DEFAULT NULL COMMENT 'Date/Time Last Archived: Date and Time the record was last archived. Reference date for physical archiving of records. Set to NULL on default or after record was archived. {"label":"Date/Time Last Archived","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0"}',
  `last_archived_by` int unsigned DEFAULT NULL COMMENT 'Last Archived By: User ID who last archived the record. {"label":"Last Archived By","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0", "joinfldval":"username"}',
  `dt_restored` datetime DEFAULT NULL COMMENT 'Date/Time Last Restored: Date and Time the record was last restored. Set to NULL on default or after record was restored. {"label":"Date/Time Last Restored","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0"}',
  `last_restored_by` int unsigned DEFAULT NULL COMMENT 'Last Restored By: User ID who last restored the record. {"label":"Last Restored By","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0", "joinfldval":"username"}',
  `dt_last_modified` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT 'Date/Time Last Modified: Date and Time the records was last modified either through front or back end. {"label":"Date/Time Last Modified","visible":"false","searchable":"false","formtag":"text","list":"0","view":"1","add_edit":"0"}',
  `urban_rural` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  PRIMARY KEY (`barangay_id`),
  KEY `municipality_city_idx` (`city_id`) USING BTREE,
  KEY `inserted_by` (`inserted_by`) USING BTREE,
  KEY `last_updated_by` (`last_updated_by`) USING BTREE,
  KEY `last_archived_by` (`last_archived_by`) USING BTREE,
  KEY `last_restored_by` (`last_restored_by`) USING BTREE,
  FULLTEXT KEY `fulltext_barangay` (`name`,`code`,`geocode`,`psa_code`),
  CONSTRAINT `lib_psgc_barangay_ibfk_1` FOREIGN KEY (`city_id`) REFERENCES `lib_psgc_city` (`city_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `lib_psgc_barangay_ibfk_2` FOREIGN KEY (`inserted_by`) REFERENCES `_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `lib_psgc_barangay_ibfk_3` FOREIGN KEY (`last_updated_by`) REFERENCES `_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `lib_psgc_barangay_ibfk_4` FOREIGN KEY (`last_archived_by`) REFERENCES `_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `lib_psgc_barangay_ibfk_5` FOREIGN KEY (`last_restored_by`) REFERENCES `_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=42312 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Library of PSGC Barangay: Library Management for PSGC Barangay';
